function buildMotoTier(
  baseTuples: RawTuple[],
  difficulty: DifficultyLevel,
  targetCount: number,
  extraPool: Array<[string, string, string, string, string]>,
  diagramDefault: DiagramType
): SeedQuestionItem[] {
  const items: SeedQuestionItem[] = [];
  for (let i = 0; i < baseTuples.length && items.length < targetCount; i++) {
    const [qText, opts, exp, diag, tags] = baseTuples[i];
    items.push({
      code: `moto_${difficulty.toLowerCase().replace(/\s+/g, '_')}_${items.length + 1}`,
      categorySlug: 'motorcycles',
      difficulty,
      questionText: qText,
      options: opts,
      explanation: exp,
      diagramType: diag,
      tags,
      estimatedTimeSec: difficulty === 'Easy' ? 15 : difficulty === 'Normal' ? 25 : difficulty === 'Hard' ? 40 : 60,
    });
  }

  let idx = 0;
  while (items.length < targetCount) {
    const fact = extraPool[idx % extraPool.length];
    const variantRound = Math.floor(idx / extraPool.length);
    const [subject, correctDesc, w1, w2, w3] = fact;
    const questionText =
      variantRound === 0
        ? `In motorcycle engineering and dynamics, what is the primary mechanism and effect of ${subject}?`
        : variantRound === 1
        ? `When evaluating motorcycle chassis or powertrain performance, which statement accurately describes ${subject}?`
        : `During a technical inspection or track setup, how does ${subject} influence motorcycle behavior?`;

    items.push({
      code: `moto_${difficulty.toLowerCase().replace(/\s+/g, '_')}_${items.length + 1}`,
      categorySlug: 'motorcycles',
      difficulty,
      questionText,
      options: [correctDesc, w1, w2, w3],
      explanation: `${subject}: ${correctDesc}.`,
      diagramType: idx % 3 === 0 ? diagramDefault : 'none',
      tags: ['motorcycles', 'dynamics', subject.toLowerCase().split(' ')[0]],
      estimatedTimeSec: difficulty === 'Hard' ? 40 : 60,
    });
    idx++;
  }

  return items;
}

